using Alterverse.Characters;using Alterverse.Match;using UnityEngine;
namespace Alterverse.Combat
{
[RequireComponent(typeof(Health))]public sealed class SoftTargeting:MonoBehaviour
{
[SerializeField]private float stickSeconds=1.25f;private readonly Collider[] buffer=new Collider[48];private Health current,self;private float stickyUntil;private TeamMember team;public Health Current=>Valid(current)?current:null;private void Awake(){team=GetComponent<TeamMember>();self=GetComponent<Health>();}
public Health Acquire(float range,Vector3 aimDirection,bool preferHeroes=true){if(Valid(current)&&Time.time<stickyUntil&&(current.transform.position-transform.position).sqrMagnitude<=range*range*1.25f)return current;int count=Physics.OverlapSphereNonAlloc(transform.position,range,buffer,~0,QueryTriggerInteraction.Ignore);Health best=null;float bestScore=float.MinValue;Vector3 aim=aimDirection;aim.y=0;if(aim.sqrMagnitude<.05f)aim=transform.forward;aim.Normalize();for(int i=0;i<count;i++){Health h=buffer[i]?.GetComponentInParent<Health>();if(!Valid(h))continue;Vector3 d=h.transform.position-transform.position;d.y=0;float dist=Mathf.Max(.01f,d.magnitude),alignment=Vector3.Dot(aim,d/dist);bool hero=h.GetComponent<HeroIdentity>()!=null;bool objective=h.GetComponent<DimensionPlanet>()!=null;float score=(range-dist)*1.2f+alignment*3.5f+(preferHeroes&&hero?3f:0)+(objective?1.2f:0);if(score>bestScore){bestScore=score;best=h;}}current=best;stickyUntil=Time.time+stickSeconds;return current;}
public void Release(){current=null;stickyUntil=0;}public void RegisterOffensiveAction(){if(Valid(current))stickyUntil=Time.time+stickSeconds;}private bool Valid(Health h){if(h==null||h.IsDead||h==self)return false;DimensionPlanet planet=h.GetComponent<DimensionPlanet>();if(planet!=null)return planet.Available;TeamMember other=h.GetComponent<TeamMember>();if(other!=null&&team!=null)return other.Team!=team.Team;LaneMinion minion=h.GetComponent<LaneMinion>();if(minion!=null)return minion.Team!=(team!=null?team.Team:0);LaneTower tower=h.GetComponent<LaneTower>();if(tower!=null)return tower.Team!=(team!=null?team.Team:0);return false;}
}
}
